Coupling.real_enum_expect_product
     : forall (R : reals.Real.type) (A B C : Type) (mu : list (reals.Real.sort R * A))
         (nu : list (reals.Real.sort R * B)) (w : A -> B -> reals.Real.sort R)
         (h : A -> B -> C) (f : C -> reals.Real.sort R),
       @Representation.real_enum_expect R C f (@Coupling.real_enum_product R A B C mu nu w h) =
       @Representation.real_enum_expect R A
         (fun x : A =>
          @Representation.real_enum_expect R B
            (fun y : B =>
             @ssralg.GRing.mul (reals.Real.Exports.reals_Real__to__GRing_SemiRing R)
               (w x y) (f (h x y))) nu) mu

Coupling.subenumR_glue_raw_left
     : forall (R : reals.Real.type) (A B C : Type) (j : Representation.SubEnumR R (A * B))
         (k : Representation.SubEnumR R (B * C)),
       (forall f : B -> reals.Real.sort R,
        @Representation.subenumR_expect R (A * B) j (fun xy : A * B => f (@snd A B xy)) =
        @Representation.subenumR_expect R (B * C) k (fun yz : B * C => f (@fst B C yz))) ->
       forall f : A -> reals.Real.sort R,
       @Representation.real_enum_expect R (A * C) (fun xz : A * C => f (@fst A C xz))
         (@Coupling.real_enum_product R (A * B) (B * C) (A * C)
            (@Representation.subenumR_raw R (A * B) j) (@Representation.subenumR_raw R (B * C) k)
            (fun (xy : A * B) (yz : B * C) =>
             if boolp.asbool (@snd A B xy = @fst B C yz)
             then
              @ssralg.GRing.inv (reals.Real.Exports.reals_Real__to__GRing_UnitRing R)
                (@Representation.subenumR_expect R (B * C) k
                   (fun yz0 : B * C => Coupling.real_indicator R (@snd A B xy = @fst B C yz0)))
             else
              @ssralg.GRing.zero
                (ssralg.GRing.UnitRing.Exports.GRing_UnitRing__to__GRing_Nmodule
                   (reals.Real.Exports.reals_Real__to__GRing_UnitRing R)))
            (fun (xy : A * B) (yz : B * C) => (@fst A B xy, @snd B C yz))) =
       @Representation.subenumR_expect R (A * B) j (fun xy : A * B => f (@fst A B xy))

Coupling.subenumR_glue_raw_right
