RelationalValidation.subenumR_native_model_lub
     : forall (R : reals.Real.type) (A : Type) (c : nat -> Representation.SubEnumR R A)
         (out : Representation.SubEnumR R A),
       (forall (n : nat) (f : A -> reals.Real.sort R),
        @Expectation.oval_test R A f ->
        is_true
          (@order.Order.le ssrnum.ring_display (reals.Real.Exports.reals_Real__to__Order_POrder R)
             (@Expectation.oval_eval R A (@Domain.subenumR_domain R A (c n)) f)
             (@Expectation.oval_eval R A (@Domain.subenumR_domain R A (c (S n))) f))) ->
       @Omega.sem_lub (Representation.SubEnumR R) (Measure.SubEnumR_SemanticMeasure R)
         (Omega.SubEnumR_SemanticOmega R) A c out ->
       forall f : A -> reals.Real.sort R,
       @Expectation.oval_test R A f ->
       @Expectation.oval_sup R
         (fun n : nat => @Expectation.oval_eval R A (@Domain.subenumR_domain R A (c n)) f) =
       @Expectation.oval_eval R A (@Domain.subenumR_domain R A out) f

